INSERT INTO daily_focus_questions (id, chapter, topic, difficulty, type, body, is_active) VALUES
  ('DF2-F6E70FBB', 'Money Basics', 'money_basics', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "Which of the following best describes money?", "options": ["A government decree that fixes prices", "Anything widely accepted as payment for goods and services", "A physical object that must be made of gold", "A promise from a bank to lend"], "answer": "Anything widely accepted as payment for goods and services", "explanation": "Money works because people agree to accept it in exchange for value; form matters less than trust.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-E6BE1A5D', 'Money Basics', 'inflation', 'beginner', 'true_false', '{"type": "true_false", "difficulty": "beginner", "question": "A rise in the price of one product, such as boba tea, is the same as economy-wide inflation.", "answer": false, "explanation": "Inflation is a broad increase in prices across the economy, not a single item becoming more expensive.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-079F643B', 'Money Basics', 'interest', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "If Rp 10,000,000 in a deposit earns 5% simple interest per year, how much interest do you earn in one year?", "options": ["Rp 500,000", "Rp 5,000,000", "Rp 50,000", "Rp 10,500,000"], "answer": "Rp 500,000", "explanation": "Simple interest is calculated only on the original principal: 5% of Rp 10,000,000 is Rp 500,000.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-8411F95E', 'Money Basics', 'income_wealth', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "Which statement best separates income from wealth?", "options": ["Income is what you keep; wealth is what you earn", "Income is money coming in; wealth is what you own minus what you owe", "Income is the same as wealth", "Wealth is only cash in a savings account"], "answer": "Income is money coming in; wealth is what you own minus what you owe", "explanation": "Income is a flow over time. Wealth is a stock at a point in time: assets minus liabilities.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-E594EBC8', 'Money Basics', 'needs_vs_wants', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "You have Rp 200,000 and must choose between lunch or a game skin. Lunch keeps you productive; the skin is cosmetic. Which is closer to a need?", "options": ["The game skin", "Lunch", "Both are needs", "Neither is a need"], "answer": "Lunch", "explanation": "A need supports your health and ability to function; a want is nice to have but optional.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-4662E391', 'Money Basics', 'assets_liabilities', 'beginner', 'true_false', '{"type": "true_false", "difficulty": "beginner", "question": "An item can behave like an asset for one person and a liability for another depending on how it is used.", "answer": true, "explanation": "The same object can produce value or drain money based on use, not just the label.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-CCF5264D', 'Money Basics', 'risk_basics', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "Which choice is an example of a risk that cannot be eliminated, only managed?", "options": ["Keeping cash at home and losing it to theft or inflation", "Putting all money in one friend''s business", "Buying only government bonds", "Avoiding all financial decisions"], "answer": "Keeping cash at home and losing it to theft or inflation", "explanation": "Every financial choice carries some risk; even cash faces inflation and theft risk.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-7F1B9F1F', 'Money Basics', 'time_value_money', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "What is the main reason Rp 1,000,000 today is generally worth more than Rp 1,000,000 in five years?", "options": ["Money today can be invested or used immediately", "Banknotes become physically smaller", "Future money is illegal", "Prices always fall"], "answer": "Money today can be invested or used immediately", "explanation": "Money has time value because it can earn returns and meet needs sooner.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-80D69164', 'Money Basics', 'inflation', 'beginner', 'fill_blank', '{"type": "fill_blank", "difficulty": "beginner", "question": "Inflation slowly reduces the _____ of money, meaning the same amount buys less over time.", "answer": "purchasing power", "explanation": "Purchasing power is what your money can actually buy; inflation erodes it.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-A3FBE19C', 'Money Basics', 'money_basics', 'beginner', 'select_all', '{"type": "select_all", "difficulty": "beginner", "question": "Select ALL the roles money commonly plays.", "options": ["Medium of exchange", "Store of value", "Unit of account", "Guarantee of profit"], "answer": ["Medium of exchange", "Store of value", "Unit of account"], "explanation": "Money lets people trade, save purchasing power, and compare prices. It does not guarantee profit.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-A233A7C7', 'Money Basics', 'needs_vs_wants', 'beginner', 'ordering', '{"type": "ordering", "difficulty": "beginner", "question": "Put these steps in the right order for checking if a purchase is a need or a want.", "options": ["Ask if you can live or function without it", "Check if it fits your budget", "Decide whether to buy now or later", "Buy immediately"], "answer": ["Ask if you can live or function without it", "Check if it fits your budget", "Decide whether to buy now or later"], "explanation": "First classify the item, then check affordability, then decide timing.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-FE33EC26', 'Money Basics', 'interest', 'beginner', 'word_bank', '{"type": "word_bank", "difficulty": "beginner", "question": "Fill in the blanks: Compound interest earns interest on both the original _____ and the interest already added.", "options": ["principal", "amount", "balance"], "answer": ["principal"], "explanation": "Compound interest grows faster because it applies to the principal plus accumulated interest.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-F73B3A95', 'Money Basics', 'assets_liabilities', 'beginner', 'matching', '{"type": "matching", "difficulty": "beginner", "question": "Match each term with its meaning.", "pairs": [["Asset", "Something that can produce value"], ["Liability", "Something that costs you money"], ["Income", "Money coming in"], ["Wealth", "Assets minus liabilities"]], "answer": {"Asset": "Something that can produce value", "Liability": "Something that costs you money", "Income": "Money coming in", "Wealth": "Assets minus liabilities"}, "explanation": "These four terms form the basic vocabulary of a personal balance sheet.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-0EE776E7', 'Money Basics', 'risk_basics', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "Which of the following is the safest place for money you might need next week?", "options": ["A separate savings account", "A speculative stock", "A locked one-year deposit", "A friend''s borrowed wallet"], "answer": "A separate savings account", "explanation": "Short-term money should be safe and accessible, not locked or volatile.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-A5AA9009', 'Money Basics', 'income_wealth', 'beginner', 'true_false', '{"type": "true_false", "difficulty": "beginner", "question": "Wealth is measured by how much you earn each month.", "answer": false, "explanation": "Wealth is assets minus liabilities; high earners can have low or negative wealth if they spend and borrow heavily.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-9D73517A', 'Money Life Skills', 'budgeting', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "A good first step in building a budget is to:", "options": ["Track where your money actually goes for a month", "Buy a premium finance app", "Borrow money to cover expenses", "Set aspirational spending targets"], "answer": "Track where your money actually goes for a month", "explanation": "You cannot improve a budget you do not understand. Start with honest tracking.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-C94DA484', 'Money Life Skills', 'saving_habits', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "What does ''pay yourself first'' usually mean?", "options": ["Save a planned amount before spending on wants", "Pay all bills first", "Treat yourself to something nice every payday", "Lend money to friends first"], "answer": "Save a planned amount before spending on wants", "explanation": "Automating savings before discretionary spending makes consistency easier.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-50E5823A', 'Money Life Skills', 'spending_behavior', 'beginner', 'true_false', '{"type": "true_false", "difficulty": "beginner", "question": "A flash sale with 70% off is always a good deal if you save money compared to the original price.", "answer": false, "explanation": "A discount is only a saving if the purchase was already planned and fits your budget; otherwise it is unplanned spending.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-C5D19E3E', 'Money Life Skills', 'behavioral_finance', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "Which habit best helps you avoid impulse spending?", "options": ["Wait 24-48 hours before non-essential purchases", "Save payment details in every app", "Shop when bored", "Follow every influencer sale"], "answer": "Wait 24-48 hours before non-essential purchases", "explanation": "A cooling-off period turns many impulse wants into forgotten wants.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-3A965096', 'Money Life Skills', 'budgeting', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "Using the 50/30/20 rule, what does the 50% typically cover?", "options": ["Needs", "Wants", "Savings and debt repayment", "Entertainment"], "answer": "Needs", "explanation": "The 50/30/20 rule allocates 50% to needs, 30% to wants, and 20% to savings and debt repayment.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-7100A62F', 'Money Life Skills', 'spending_behavior', 'beginner', 'fill_blank', '{"type": "fill_blank", "difficulty": "beginner", "question": "A spending _____ is anything that nudges you to spend more than you planned.", "answer": "trigger", "explanation": "Triggers can be notifications, emotions, social pressure, or app designs that encourage impulse buying.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-5E0EC026', 'Money Life Skills', 'spending_behavior', 'beginner', 'select_all', '{"type": "select_all", "difficulty": "beginner", "question": "Select ALL useful ways to reduce subscription creep.", "options": ["Review bank statements monthly", "Cancel unused services", "Share family plans where allowed", "Add new trials every week"], "answer": ["Review bank statements monthly", "Cancel unused services", "Share family plans where allowed"], "explanation": "Regular reviews and cancelling unused services keep recurring costs aligned with your priorities.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-C2B6440E', 'Money Life Skills', 'budgeting', 'beginner', 'ordering', '{"type": "ordering", "difficulty": "beginner", "question": "Order these budgeting steps from first to last.", "options": ["Record income", "Track spending", "Set goals", "Allocate money", "Review and adjust"], "answer": ["Record income", "Track spending", "Set goals", "Allocate money", "Review and adjust"], "explanation": "Budgeting starts with knowing what you have, then where it goes, then deciding where it should go.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-EAD1A302', 'Money Life Skills', 'behavioral_finance', 'beginner', 'true_false', '{"type": "true_false", "difficulty": "beginner", "question": "Mental accounting means treating money differently depending on where it came from or how it is labelled.", "answer": true, "explanation": "Mental accounting can lead to overspending a ''bonus'' while carefully budgeting a salary, even though money is fungible.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-7CA072ED', 'Money Life Skills', 'spending_behavior', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "Which of the following is a sign that a spending habit may be becoming a trap?", "options": ["You hide purchases from people close to you", "You track every receipt", "You wait for sales on planned items", "You compare prices before buying"], "answer": "You hide purchases from people close to you", "explanation": "Secrecy and guilt around spending are warning signs that a habit is harming your finances.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-61199921', 'Money Life Skills', 'saving_habits', 'beginner', 'fill_blank', '{"type": "fill_blank", "difficulty": "beginner", "question": "Automating a transfer to savings on payday is one way to make saving a _____ habit.", "answer": "consistent", "explanation": "Automation reduces the willpower needed to save and makes consistency automatic.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-FE9A1DA7', 'Money Life Skills', 'budgeting', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "If your income is irregular, what is the safest budgeting approach?", "options": ["Budget based on your lowest recent month and save the surplus in better months", "Spend whatever comes in", "Borrow against next month''s expected income", "Ignore budgeting until income stabilizes"], "answer": "Budget based on your lowest recent month and save the surplus in better months", "explanation": "Irregular income needs a conservative baseline so lean months do not create debt.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-6DE7864D', 'Money Life Skills', 'saving_habits', 'beginner', 'word_bank', '{"type": "word_bank", "difficulty": "beginner", "question": "Complete the sentence: Paying yourself first means saving before you _____.", "options": ["spend on wants", "pay bills", "earn income", "invest"], "answer": ["spend on wants"], "explanation": "The idea is to prioritise future needs by saving before discretionary spending.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-2B9CAE52', 'Money Life Skills', 'budgeting', 'beginner', 'true_false', '{"type": "true_false", "difficulty": "beginner", "question": "A budget should never be changed once it is set.", "answer": false, "explanation": "A budget is a living plan. Life changes, so the budget should be reviewed and adjusted regularly.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-DB529F6F', 'Protect Yourself', 'scam_defense', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "Which is the safest response to an Instagram DM promising 20% guaranteed monthly returns?", "options": ["Check OJK''s investment alert list and ignore the message", "Send a small amount to test", "Share the link with friends", "Ask for the manager''s WhatsApp"], "answer": "Check OJK''s investment alert list and ignore the message", "explanation": "Guaranteed high returns are a classic scam signal. Verify licenses through official OJK channels.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-522BB17F', 'Protect Yourself', 'phishing_social_engineering', 'beginner', 'true_false', '{"type": "true_false", "difficulty": "beginner", "question": "A real bank officer may ask for your OTP to verify a transaction over the phone.", "answer": false, "explanation": "Legitimate banks never ask for OTPs or passwords. Treat any such request as a scam.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-E4EC4916', 'Protect Yourself', 'ojk_license_check', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "What is the main purpose of checking an OJK license before investing?", "options": ["To confirm the product or platform is legally supervised", "To guarantee profit", "To avoid paying taxes", "To get a higher return"], "answer": "To confirm the product or platform is legally supervised", "explanation": "OJK supervision means there are rules and dispute channels; it does not guarantee returns.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-C6A3CF32', 'Protect Yourself', 'scam_defense', 'beginner', 'select_all', '{"type": "select_all", "difficulty": "beginner", "question": "Select ALL common red flags of an investment scam.", "options": ["Guaranteed high returns", "Pressure to recruit friends", "Urgency and limited slots", "Registered on OJK''s official list"], "answer": ["Guaranteed high returns", "Pressure to recruit friends", "Urgency and limited slots"], "explanation": "Registration on OJK''s list is a green flag, not a red flag.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-31EFDD7B', 'Protect Yourself', 'phishing_social_engineering', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "A message says ''Your package is stuck, click here to pay customs.'' What should you do first?", "options": ["Open the official courier app or website and check the tracking number", "Click the link and enter details", "Reply with your address", "Forward to family"], "answer": "Open the official courier app or website and check the tracking number", "explanation": "Phishing often uses fake delivery issues. Always verify through official channels.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-4E083EA9', 'Protect Yourself', 'ojk_license_check', 'beginner', 'fill_blank', '{"type": "fill_blank", "difficulty": "beginner", "question": "In Indonesia, you can use OJK''s investment _____ list to check whether an investment offer is illegal.", "answer": "alerta", "explanation": "OJK publishes an alert list of illegal investments and unauthorised entities.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-2322E413', 'Protect Yourself', 'mlm_pyramid', 'beginner', 'true_false', '{"type": "true_false", "difficulty": "beginner", "question": "An MLM scheme that pays you mainly for recruiting new members rather than selling real products is sustainable.", "answer": false, "explanation": "Recruitment-focused MLMs collapse when recruitment slows because there is no real product income.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-87D89923', 'Protect Yourself', 'scam_defense', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "Which detail should make you most suspicious of a ''financial coach'' offering guaranteed returns?", "options": ["They promise no risk and high profit", "They ask about your goals", "They explain fees clearly", "They are registered with OJK"], "answer": "They promise no risk and high profit", "explanation": "Risk and return are linked; anyone promising high returns with no risk is either lying or scamming.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-21B00D6C', 'Protect Yourself', 'scam_defense', 'beginner', 'ordering', '{"type": "ordering", "difficulty": "beginner", "question": "Order the safest response when you receive a suspicious investment message.", "options": ["Stop and do not click", "Verify the license on OJK''s official site", "Delete or report the message", "Warn friends if it is a known scam"], "answer": ["Stop and do not click", "Verify the license on OJK''s official site", "Delete or report the message", "Warn friends if it is a known scam"], "explanation": "Pause, verify, act, and share warnings only after confirmation.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-62B573F6', 'Protect Yourself', 'phishing_social_engineering', 'beginner', 'word_bank', '{"type": "word_bank", "difficulty": "beginner", "question": "Never share your _____ or password with anyone claiming to be from a bank.", "options": ["OTP", "PIN", "account number", "name"], "answer": ["OTP"], "explanation": "OTP and passwords are secrets. No legitimate bank employee will ask for them.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-A976938B', 'Protect Yourself', 'scam_defense', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "A friend invites you to join a ''private crypto signal group'' with guaranteed profits. What is the wisest move?", "options": ["Decline and remind them that guarantees in crypto are a red flag", "Invest immediately to not miss out", "Borrow money to join", "Recruit more friends"], "answer": "Decline and remind them that guarantees in crypto are a red flag", "explanation": "Guaranteed profits, especially in crypto, are a major warning sign.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-00A92EF3', 'Protect Yourself', 'ojk_license_check', 'beginner', 'true_false', '{"type": "true_false", "difficulty": "beginner", "question": "Checking OJK''s license is only necessary for large investments.", "answer": false, "explanation": "Scams target small amounts too. Always verify, regardless of how much you plan to invest.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-FD1BFF06', 'Protect Yourself', 'scam_defense', 'beginner', 'matching', '{"type": "matching", "difficulty": "beginner", "question": "Match the scam type with its hallmark.", "pairs": [["Ponzi", "Pays old investors with new investors'' money"], ["Pyramid", "Rewards recruiting more than selling"], ["Phishing", "Pretends to be a trusted entity to steal data"], ["Pump and dump", "Artificially hypes an asset then sells"]], "answer": {"Ponzi": "Pays old investors with new investors'' money", "Pyramid": "Rewards recruiting more than selling", "Phishing": "Pretends to be a trusted entity to steal data", "Pump and dump": "Artificially hypes an asset then sells"}, "explanation": "Recognising the pattern helps you spot scams before losing money.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-44B7BED1', 'Protect Yourself', 'scam_defense', 'beginner', 'fill_blank', '{"type": "fill_blank", "difficulty": "beginner", "question": "If an offer sounds too good to be _____, it usually is.", "answer": "true", "explanation": "Extraordinary claims with little risk are one of the oldest scam signs.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-50993F7A', 'Let''s Talk About Debt', 'good_debt_vs_bad_debt', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "Which debt is most likely to be ''good debt''?", "options": ["A student loan that increases your future income", "A PayLater purchase of trendy clothes", "A credit card used for dining out every weekend", "A loan for a luxury vacation"], "answer": "A student loan that increases your future income", "explanation": "Good debt helps you build income or wealth; bad debt buys depreciating wants.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-F8558FBD', 'Let''s Talk About Debt', 'credit_cards', 'beginner', 'true_false', '{"type": "true_false", "difficulty": "beginner", "question": "Paying only the minimum on a credit card keeps the balance from growing.", "answer": false, "explanation": "Minimum payments usually leave most of the balance subject to interest, so the debt can grow.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-EE3C684C', 'Let''s Talk About Debt', 'debt_repayment', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "You have Rp 2,000,000 extra to pay debt. You owe Rp 5,000,000 on a credit card at 24% annual interest and Rp 2,000,000 to a friend at 0%. Which should you pay first using the avalanche method?", "options": ["The credit card", "The friend", "Split equally", "Pay neither"], "answer": "The credit card", "explanation": "Avalanche prioritises the highest-interest debt while keeping minimum payments on the rest.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-B56391FF', 'Let''s Talk About Debt', 'pay_later', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "What is the biggest hidden danger of using PayLater for small wants?", "options": ["It hides the full cost and encourages impulse buying", "It is always illegal", "It has no fees", "It builds credit history automatically"], "answer": "It hides the full cost and encourages impulse buying", "explanation": "Small instalments feel affordable, but fees and impulse purchases can add up quickly.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-0A3FB5AD', 'Let''s Talk About Debt', 'debt_traps', 'beginner', 'select_all', '{"type": "select_all", "difficulty": "beginner", "question": "Select ALL signs that you may be falling into a debt trap.", "options": ["Borrowing to pay off other debt", "Hiding bills from family", "Paying only minimums every month", "Tracking spending weekly"], "answer": ["Borrowing to pay off other debt", "Hiding bills from family", "Paying only minimums every month"], "explanation": "Tracking spending weekly is healthy; the others are warning signs.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-771F18E1', 'Let''s Talk About Debt', 'debt_repayment', 'beginner', 'fill_blank', '{"type": "fill_blank", "difficulty": "beginner", "question": "The debt _____ method targets the smallest balance first to build motivation.", "answer": "snowball", "explanation": "Snowball gives quick wins by clearing small debts first; avalanche usually saves more interest.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-A04E3766', 'Let''s Talk About Debt', 'credit_cards', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "Which behaviour turns a credit card from a useful tool into a costly problem?", "options": ["Treating the credit limit as extra income", "Paying the full balance every month", "Using it only for planned groceries", "Setting an automatic full payment"], "answer": "Treating the credit limit as extra income", "explanation": "A credit card is a short-term loan; the limit is not income.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-1CA995D0', 'Let''s Talk About Debt', 'good_debt_vs_bad_debt', 'beginner', 'true_false', '{"type": "true_false", "difficulty": "beginner", "question": "A motorbike loan is always bad debt because it is a vehicle.", "answer": false, "explanation": "A motorbike loan can be good debt if the bike is used to earn income that exceeds the repayments.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-815983EF', 'Let''s Talk About Debt', 'debt_repayment', 'beginner', 'ordering', '{"type": "ordering", "difficulty": "beginner", "question": "Order the steps for paying off debt responsibly.", "options": ["Stop adding new debt", "List all debts with interest rates and minimums", "Pay minimums on every debt", "Put extra toward the highest-interest debt"], "answer": ["Stop adding new debt", "List all debts with interest rates and minimums", "Pay minimums on every debt", "Put extra toward the highest-interest debt"], "explanation": "A clear plan stops panic and prevents missed payments.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-EE28A752', 'Let''s Talk About Debt', 'debt_repayment', 'beginner', 'word_bank', '{"type": "word_bank", "difficulty": "beginner", "question": "When you cannot make a payment, the best first step is to _____ the lender early.", "options": ["contact", "ignore", "avoid", "block"], "answer": ["contact"], "explanation": "Early communication often leads to restructuring options and protects your credit record.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-B3197593', 'Let''s Talk About Debt', 'debt_traps', 'beginner', 'multiple_choice', '{"type": "multiple_choice", "difficulty": "beginner", "question": "Why can minimum payments on high-interest debt be dangerous?", "options": ["They keep the debt alive and growing through interest", "They make the debt disappear faster", "They have no fees", "They improve your credit score instantly"], "answer": "They keep the debt alive and growing through interest", "explanation": "Minimum payments mostly cover interest, so the principal shrinks slowly or not at all.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-586CA19E', 'Let''s Talk About Debt', 'pay_later', 'beginner', 'true_false', '{"type": "true_false", "difficulty": "beginner", "question": "PayLater is safe as long as the provider is licensed by OJK.", "answer": false, "explanation": "Even licensed PayLater can lead to overspending and fees; license is necessary but not sufficient for safety.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-3A68F423', 'Let''s Talk About Debt', 'good_debt_vs_bad_debt', 'beginner', 'matching', '{"type": "matching", "difficulty": "beginner", "question": "Match each borrowing scenario with its likely category.", "pairs": [["Student loan for a certification", "Often good debt"], ["PayLater for a hoodie", "Usually bad debt"], ["Credit card paid in full monthly", "Useful tool"], ["Borrowing to gamble", "Dangerous debt"]], "answer": {"Student loan for a certification": "Often good debt", "PayLater for a hoodie": "Usually bad debt", "Credit card paid in full monthly": "Useful tool", "Borrowing to gamble": "Dangerous debt"}, "explanation": "Category depends on purpose, cost, and whether the debt produces value.", "parameters": {}}'::jsonb, TRUE),
  ('DF2-A9C800BA', 'Let''s Talk About Debt', 'good_debt_vs_bad_debt', 'beginner', 'fill_blank', '{"type": "fill_blank", "difficulty": "beginner", "question": "When evaluating debt, always compare the interest rate to the _____ the debt might create.", "answer": "value", "explanation": "Productive debt should create more value than it costs; consumptive debt rarely does.", "parameters": {}}'::jsonb, TRUE),
