-- Migration: KO-FOCUS-001 — Separate Daily Focus question bank from lesson content
-- Generated from daily-focus-quiz-bank-v2-2026-07-26.csv
-- Scope: 123 bilingual questions across 8 chapters + Foundation 0.

BEGIN;

-- 1. Create a standalone table for Daily Focus questions.
CREATE TABLE IF NOT EXISTS daily_focus_questions (
  id TEXT PRIMARY KEY,
  chapter TEXT NOT NULL,
  topic TEXT NOT NULL,
  difficulty TEXT NOT NULL,
  type TEXT NOT NULL,
  body JSONB NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMENT ON TABLE daily_focus_questions IS 'Standalone question bank for Daily Focus, separate from lesson content_variants.';

-- 2. Seed the bank with fresh questions.

-- 3. Update Daily Focus generation to use the separate bank.
-- The engine currently supports multiple_choice, true_false, and swipe_yes_no;
-- other types are stored for future engine support.
CREATE OR REPLACE FUNCTION ensure_daily_focus_challenge(
  p_user_id UUID,
  p_time_zone TEXT
)
RETURNS daily_focus_challenges
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_time_zone TEXT := assert_focus_time_zone(p_time_zone);
  v_today DATE := (NOW() AT TIME ZONE v_time_zone)::DATE;
  v_profile focus_profiles;
  v_questions JSONB;
  v_challenge daily_focus_challenges;
BEGIN
  VALUES (p_user_id, v_time_zone)
  ON CONFLICT (user_id) DO NOTHING;

  SELECT * INTO v_profile
  FROM focus_profiles
  WHERE user_id = p_user_id
  FOR UPDATE;

  UPDATE focus_profiles
  SET time_zone = v_time_zone,
      updated_at = NOW()
  WHERE user_id = p_user_id
  RETURNING * INTO v_profile;

  SELECT COALESCE(jsonb_agg(question_body), '[]'::JSONB)
  INTO v_questions
  FROM (
    SELECT dfq.body AS question_body
    FROM daily_focus_questions AS dfq
    WHERE dfq.is_active = TRUE
      AND dfq.type IN ('multiple_choice', 'true_false', 'swipe_yes_no')
      AND dfq.body ? 'question'
      AND dfq.body ? 'answer'
    ORDER BY md5(dfq.id || p_user_id::TEXT || v_today::TEXT)
    LIMIT 5
  ) AS selectable_questions;

  IF jsonb_array_length(v_questions) <> 5 THEN
    RAISE EXCEPTION 'Daily Focus needs at least five active binary or multiple-choice question variants';
  END IF;

    user_id, challenge_date, time_zone, max_focus, focus_remaining, questions
  ) VALUES (
    p_user_id, v_today, v_time_zone, v_profile.max_focus, v_profile.max_focus, v_questions
  )
  ON CONFLICT (user_id, challenge_date) DO NOTHING;

  SELECT * INTO v_challenge
  FROM daily_focus_challenges
  WHERE user_id = p_user_id AND challenge_date = v_today;

  RETURN v_challenge;
END;
$$;

COMMIT;